'use strict';
// Homeroom's sync with main (worker/run-cc.sh, MODE=sync) when a proposal
// and main each added a schema migration: the manifest conflict is
// regenerated by scripts/record-schema-migration.js --onto, never handed to
// the model. On 2 Nov 2026 a model-merged manifest kept two 0013s in the
// wrong order and main stopped loading its migrations.
const { test } = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const crypto = require('node:crypto');
const { execFileSync, spawnSync } = require('node:child_process');

const ROOT = path.join(__dirname, '..');
const RUN_CC = path.join(ROOT, 'worker', 'run-cc.sh');
const BRANCH = 'dev/homeroom_bot-6138';
const MANIFEST = 'src/db/migrations/manifest.json';
const hash = sql => crypto.createHash('sha256').update(sql).digest('hex');
const ENV = { ...process.env, GIT_CONFIG_GLOBAL: os.devNull, GIT_CONFIG_NOSYSTEM: '1', GIT_TERMINAL_PROMPT: '0',
  GIT_AUTHOR_NAME: 't', GIT_AUTHOR_EMAIL: 't@example.test', GIT_COMMITTER_NAME: 't', GIT_COMMITTER_EMAIL: 't@example.test' };
const git = (cwd, ...args) => execFileSync('git', args, { cwd, env: ENV, encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] }).trim();

// Records how it was called; resolves app.js the way a model would.
const STUB_CLAUDE = `#!/usr/bin/env node
const fs = require('fs');
const args = process.argv.slice(2);
fs.writeFileSync(process.env.STUB_LOG, JSON.stringify({ prompt: args[args.indexOf('-p') + 1] }));
if (fs.existsSync('app.js')) fs.writeFileSync('app.js', 'console.log("both");\\n');
`;

// The platform's repository in small: its record command and schema source,
// a baseline, and a change on each side. `edits` run on the branch first.
function fixture(t, { branchEdits = () => {}, mainEdits = () => {} } = {}) {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'sync-schema-'));
  t.after(() => fs.rmSync(dir, { recursive: true, force: true }));
  const origin = path.join(dir, 'origin.git');
  const seed = path.join(dir, 'seed');
  git(dir, 'init', '-q', '--bare', '-b', 'main', origin);
  git(dir, 'clone', '-q', origin, seed);
  for (const file of ['scripts/record-schema-migration.js', 'src/db/schema-source.js', 'src/db/reference-data.js']) {
    fs.mkdirSync(path.dirname(path.join(seed, file)), { recursive: true });
    fs.copyFileSync(path.join(ROOT, file), path.join(seed, file));
  }
  const migrations = path.join(seed, 'src/db/migrations');
  fs.mkdirSync(migrations);
  const baseline = 'CREATE TABLE a (id int);';
  fs.writeFileSync(path.join(migrations, '0001-baseline.sql'), baseline);
  fs.writeFileSync(path.join(seed, MANIFEST), JSON.stringify({ version: 1, migrations: [
    { id: '0001-baseline', sha256: hash(baseline), schemaSha256: hash(baseline) }] }, null, 2) + '\n');
  fs.writeFileSync(path.join(seed, '.gitignore'), 'src/db/schema.sql\n');
  fs.writeFileSync(path.join(seed, 'app.js'), 'console.log(1);\n');
  git(seed, 'add', '-A'); git(seed, 'commit', '-qm', 'baseline');
  const migrate = (name, sql) => {
    fs.writeFileSync(path.join(migrations, `${name}.sql`), sql);
    execFileSync(process.execPath, ['scripts/record-schema-migration.js', name], { cwd: seed, stdio: 'pipe' });
  };
  git(seed, 'switch', '-qc', BRANCH);
  migrate('web-withdraws', 'ALTER TABLE a ADD web int;');
  branchEdits(seed);
  git(seed, 'add', '-A'); git(seed, 'commit', '-qm', 'branch');
  git(seed, 'switch', '-q', 'main');
  migrate('admin-text', 'ALTER TABLE a ADD admin text;');
  mainEdits(seed);
  git(seed, 'add', '-A'); git(seed, 'commit', '-qm', 'main');
  git(seed, 'push', '-q', 'origin', 'main', BRANCH);
  const ws = path.join(dir, 'ws');
  git(dir, 'clone', '-q', '-b', BRANCH, origin, ws);
  const bin = path.join(dir, 'bin');
  fs.mkdirSync(bin);
  fs.writeFileSync(path.join(bin, 'claude'), STUB_CLAUDE);
  fs.chmodSync(path.join(bin, 'claude'), 0o755);
  const prompt = path.join(dir, 'prompt.txt');
  fs.writeFileSync(prompt, 'Sync with main');
  return { dir, ws, bin, prompt, log: path.join(dir, 'claude.json'), branchHead: git(ws, 'rev-parse', 'HEAD') };
}

function sync(fx) {
  const ran = spawnSync('sh', [RUN_CC], { encoding: 'utf8', env: {
    ...ENV, PATH: `${fx.bin}:${process.env.PATH}`, HOME: fx.dir,
    PROMPT_FILE: fx.prompt, WORKSPACE_DIR: fx.ws, MODE: 'sync', BRANCH, SESSION_ID: '6138',
    PLATFORM_URL: 'http://127.0.0.1:1', WORKER_JWT: 'test-worker-jwt', STUB_LOG: fx.log,
    USERNODE_CGROUP_DIR: path.join(fx.dir, 'absent-cgroup'),
  } });
  const out = `${ran.stdout}${ran.stderr}`;
  return { code: ran.status, out, result: out.split('\n').find(l => l.startsWith('__USERNODE_RESULT__')) || '',
    claude: fs.existsSync(fx.log) ? JSON.parse(fs.readFileSync(fx.log, 'utf8')) : null };
}

const ids = ws => JSON.parse(fs.readFileSync(path.join(ws, MANIFEST), 'utf8')).migrations.map(m => m.id);

test('a manifest conflict is recorded on top of main by the command, with no model', t => {
  const fx = fixture(t);
  const ran = sync(fx);
  assert.equal(ran.code, 0, ran.out);
  assert.match(ran.result, /sync_result=resolved/);
  assert.match(ran.result, new RegExp(`conflict_files=${MANIFEST}( |$)`));
  assert.equal(ran.claude, null, 'the model is not asked');
  assert.deepEqual(ids(fx.ws), ['0001-baseline', 'admin-text', 'web-withdraws']);
  assert.equal(git(fx.ws, 'log', '-1', '--format=%s'), 'Merge origin/main via Homeroom sync (schema history recorded on top of main)');
  assert.equal(git(fx.ws, 'status', '--porcelain'), '', 'the generated schema.sql stays ignored');
  // The manifest is the only file the resolution touched.
  assert.deepEqual(git(fx.ws, 'diff', '--name-only', 'HEAD^2', 'HEAD').split('\n'),
    ['src/db/migrations/manifest.json', 'src/db/migrations/web-withdraws.sql']);
});

test('with other conflicts too, the model gets only those, and the history is already recorded', t => {
  const fx = fixture(t, {
    branchEdits: seed => fs.writeFileSync(path.join(seed, 'app.js'), 'console.log("branch");\n'),
    mainEdits: seed => fs.writeFileSync(path.join(seed, 'app.js'), 'console.log("main");\n'),
  });
  const ran = sync(fx);
  assert.equal(ran.code, 0, ran.out);
  assert.match(ran.result, /sync_result=resolved/);
  assert.match(ran.claude.prompt, /Conflicted files: app\.js $/m);
  assert.doesNotMatch(ran.claude.prompt, /manifest\.json/);
  assert.deepEqual(ids(fx.ws), ['0001-baseline', 'admin-text', 'web-withdraws']);
  assert.equal(git(fx.ws, 'log', '-1', '--format=%s'), 'Merge origin/main via Homeroom sync (Claude-resolved)');
});

test('a branch that edited a migration main has applied is handed back, unchanged', t => {
  const fx = fixture(t, {
    branchEdits: seed => fs.appendFileSync(path.join(seed, 'src/db/migrations/0001-baseline.sql'), '\nALTER TABLE a ADD sneaky int;'),
  });
  const ran = sync(fx);
  assert.equal(ran.code, 0, ran.out);
  assert.match(ran.out, /checksum mismatch: 0001-baseline/);
  assert.match(ran.result, /sync_result=conflict/);
  assert.equal(ran.claude, null, 'no model edits a history');
  assert.equal(git(fx.ws, 'rev-parse', 'HEAD'), fx.branchHead);
  assert.equal(git(fx.ws, 'status', '--porcelain'), '');
});
